import sys
input = sys.stdin.read
data = input().split()

w = int(data[0])
m = int(data[1])

def can_measure(w, m):
    while m > 0:
        if m % w == 0:
            m //= w
        elif m % w == 1:
            m = (m - 1) // w
        elif m % w == w - 1:
            m = (m + 1) // w
        else:
            return False
    return True

if can_measure(w, m):
    print("YES")
else:
    print("NO")

